window.RP_SESSION={"id":"S-e208fe97b15e","messages":[{"id":"RP-II-0087182","time":"2026-04-23T01:52:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"늦은 밤 오늘도 다시 종이와 잉크를 꺼내둡니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087183","time":"2026-04-23T01:53:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그대의 사랑편지에 답해드립니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087184","time":"2026-04-23T01:56:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"북쪽 찬바람이 폐에 스며들어 그대 마음 얼리지 않길 바라며, 시작합니다","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087185","time":"2026-04-23T02:00:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"좋은 아침, 좋은 오후 또 좋은 저녁, \n여기서 평소와 다름없이 지내고있어요, \n마침 의뢰도 몇개 다녀왔습니다. 모험담은 그대가 돌아오는 날 들려드릴게요.\n\n또 최근 들어 생각이 늘어나 글 쓰는 게 즐거워지기도 했습니다, 덕에 답장도 쓰네요.\n\n어쩌면 옛날 말은 정말 틀린 게 없나 봅니다. 말로 하려던 것도 이리 전할 수 있다는 것에 감사할 따름입니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087186","time":"2026-04-23T02:03:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"오래간만에 꿈을 꾸었어요.\n\n음.. 아뇨, 생각을 했어요.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087187","time":"2026-04-23T02:06:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"해야 할 것도 많을 것만 같고, 그것이 또 두렵고, 과연 내가 저 끝까지 완주할 수 있을까 의문이 들었어요.\n\n이런저런 생각에 점점 가라앉을 때,\n다시금 더욱 가라앉아 다시 떠오르기도 힘들겠다 싶었을 때ㅡ\n\n그저 함께 있는 게 즐거워지는 그대를 찾았습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087188","time":"2026-04-23T02:06:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"어쩌면 말이에요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087189","time":"2026-04-23T02:07:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"우리 인생에서 말이에요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087190","time":"2026-04-23T02:08:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"궁극적인 목표는 금은보화도, 권력도 직위도 아닌 이 순간을 살아가게 해주는 존재를 계속해서 찾아가는 것일지도 모르겠어요.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087191","time":"2026-04-23T02:08:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"그런 생각을 했고 꿈을 꿨어요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087192","time":"2026-04-23T02:09:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"... 별 상관없는 이야기만 늘어두었네요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087193","time":"2026-04-23T02:09:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"무튼 보고싶습니다.\n\n다쳐서만 오지 말아요","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087194","time":"2026-04-23T02:10:00+09:00","room":"RP II","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0087195","time":"2026-04-23T02:10:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
